import {missions} from './missions.js';
const $=s=>document.querySelector(s), KEY='realityquest-progress-v1';
const paths={grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',book:'M12 5v16 M12 5C8 2 4 3 2 4v15c3-1 6-1 10 2 4-3 7-3 10-2V4c-2-1-6-2-10 1',chart:'M4 20V11 M12 20V4 M20 20V8',wave:'M3 10v4 M7 6v12 M12 3v18 M17 7v10 M21 10v4',spark:'m12 3 3 6 6 3-6 3-3 6-3-6-6-3 6-3z',shield:'M12 3 3 7v6c0 5 9 9 9 9s9-4 9-9V7z m-5 9 3 3 6-6',image:'M3 3h18v18H3z m0 14 6-6 5 5 3-3 4 4 M16 7h.01',heart:'M12 21 3 12C-2 4 8 0 12 7c4-7 14-3 9 5z',users:'M8 13c-4 0-6 2-6 7 M16 13c4 0 6 2 6 7 M8 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6 M16 10a3 3 0 1 0 0-6 3 3 0 0 0 0 6',arrow:'M4 12h16 m-6-6 6 6-6 6',check:'m5 12 4 4L19 6',clock:'M12 7v5l3 2 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',info:'M12 11v6 M12 7h.01 M21 12a9 9 0 1 0-18 0 9 9 0 0 0 18 0',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12 M15 12a3 3 0 1 0-6 0 3 3 0 0 0 6 0'};
const icon=(n,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[n]||paths.spark}"/></svg>`;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let saved={},storageOK=true;try{const raw=JSON.parse(localStorage.getItem(KEY)||'{}');for(const m of missions){const r=raw?.[m.id];if(r&&Number.isInteger(r.score)&&r.score>=0&&r.score<=100)saved[m.id]={score:r.score};}}catch{storageOK=false;}
let view='missions',active=null,round=0,selected=null,answers=[],filter='all',sessionResult=null;
const done=()=>Object.keys(saved).length,total=()=>Object.values(saved).reduce((a,b)=>a+b.score,0);
function persist(){try{localStorage.setItem(KEY,JSON.stringify(saved));}catch{storageOK=false;}}
function say(text){$('#announcement').textContent=text;}
function shell(content){$('#app').innerHTML=`<aside class="sidebar"><a href="#" class="brand" data-nav="missions"><img src="icon.svg" alt=""/><span>reality<span class="brand-light">quest</span><sup>✦</sup></span></a><div class="sidebar-caption">YOUR AI ADVENTURE STARTS HERE</div><nav aria-label="Main navigation">${[['missions','grid','Mission hub'],['guide','book','Field guide'],['progress','chart','Your progress']].map(([v,i,t])=>`<button data-nav="${v}" class="nav-item ${view===v&&!active?'current':''}" ${view===v&&!active?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${v==='missions'?'<span class="nav-count">06</span>':''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="local-badge"><span class="status-dot"></span>YOUR SPACE. YOUR PACE.</div><p>No leaderboard. No pressure.<br>Just a little wiser every mission.</p><button class="help-button" data-help>${icon('info',17)} About & get support</button><span class="prototype">A CHILD SAFETY IN AI PROJECT</span></div></aside><div class="workspace"><header class="topbar"><span class="breadcrumb">RealityQuest <span>/</span> ${active?'In the field':view==='guide'?'Field guide':view==='progress'?'Your progress':'Mission hub'}</span><div class="player"><span class="xp">${icon('spark',15)} ${total()} XP</span><span class="avatar">R</span><span>${done()===6?'Explorer':'Rookie explorer'}</span></div></header><main id="main" tabindex="-1">${!storageOK?'<div class="storage-alert" role="status">Browser storage is unavailable. You can still play, but progress may not survive a refresh.</div>':''}${content}</main><footer><span>Built for curious minds. Designed for safer choices.</span><button data-help>Privacy & support ${icon('arrow',13)}</button></footer></div>`;bind();}
function focusMain(){const h=$('#main h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}window.scrollTo({top:0,behavior:'instant'});}
function navigate(next){if(active&&!sessionResult&&!confirm('Leave this mission? This attempt will restart. Completed progress will stay saved.'))return;active=null;sessionResult=null;view=next;render();focusMain();}
function bind(){document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=e=>{e.preventDefault();navigate(b.dataset.nav)});document.querySelectorAll('[data-help]').forEach(b=>b.onclick=()=>$('#help').showModal());document.querySelectorAll('[data-start]').forEach(b=>b.onclick=()=>startMission(b.dataset.start));document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;render();});document.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>choose(Number(b.dataset.choice)));if($('#advance'))$('#advance').onclick=advance;if($('#export'))$('#export').onclick=exportReport;if($('#reset'))$('#reset').onclick=()=>{if(confirm('Reset completed missions and XP in this browser?')){saved={};persist();render();say('Progress reset.');}};}
function render(){if(active){renderMission();return;}if(view==='guide'){renderGuide();return;}if(view==='progress'){renderProgress();return;}const next=missions.find(m=>!saved[m.id])||missions[0];const listed=missions.filter(m=>filter==='all'||(filter==='new'?!saved[m.id]:!!saved[m.id]));shell(`<section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> THE INTERNET GOT AN UPGRADE. SO CAN YOU.</div><h1>Real or AI?<br><span>You've got this.</span></h1><p>Not everything online is what it seems.<br>Build your instincts, spot the clues, and make<br class="desktop"> smarter moves — one mission at a time.</p><button class="primary" data-start="${next.id}">${done()?'Continue your quest':'Start your first mission'} ${icon('arrow')}</button><div class="hero-meta"><span>${icon('clock',14)} 3-minute missions</span><span>${icon('shield',14)} No personal data needed</span></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><span class="art-spark star-one">✦</span><span class="art-spark star-two">✧</span><div class="art-label"><span></span> INVESTIGATION IN PROGRESS</div><div class="floating-message"><div class="message-avatar">?</div><div><small>UNKNOWN SENDER</small><strong>“Trust me. It’s really me.”</strong><span>Does a familiar voice prove it?</span></div></div><div class="quest-emblem"><div class="emblem-inner">${icon('eye',80)}</div><span class="emblem-diamond"></span></div><div class="verified-card">${icon('shield',25)}<div><strong>Pause. Check. Choose.</strong><span>Your best tool is a good question.</span></div></div><div class="art-coordinate">LEVEL 01 / QUESTION EVERYTHING</div></div></section><section class="status-strip" aria-label="Your quest progress"><div class="journey-label"><span class="mini-emblem">${icon('spark',22)}</span><div><strong>Your journey</strong><span>${done()===6?'Every mission explored. Keep practicing.':'Small choices. Stronger instincts.'}</span></div></div><div class="journey-meter"><div><span>${done()} of 6 missions complete</span><strong>${Math.round(done()/6*100)}%</strong></div><progress value="${done()}" max="6" aria-label="Completed missions">${done()} of 6</progress></div><span class="journey-xp">${total()} <small>/ 600 XP</small></span></section><section class="mission-section"><div class="section-top"><div class="heading-group"><span class="eyebrow">CHOOSE YOUR NEXT CHALLENGE</span><h2>Your missions <span>06</span></h2></div><div class="filters" role="group" aria-label="Filter missions">${[['all','All missions'],['new','Not completed'],['done','Completed']].map(([v,t])=>`<button data-filter="${v}" aria-pressed="${filter===v}">${t}</button>`).join('')}</div></div><div class="mission-grid">${listed.map(m=>card(m)).join('')||'<div class="empty"><h3>No missions here yet.</h3><p>Complete a mission to add it to your collection.</p><button class="secondary" data-filter="all">See all missions</button></div>'}</div></section><section class="bottom-note">${icon('shield',20)}<p><strong>Practice here. Take your instincts everywhere.</strong> All scenarios are fictional. This is a learning game, not a tool for deciding whether real people or messages are safe.</p><button data-nav="guide">Open the field guide ${icon('arrow',17)}</button></section>`);}
function card(m){const idx=missions.indexOf(m)+1;return `<article class="mission-card ${m.color}"><div class="card-art"><div class="card-ring"></div><span class="case-label">CASE 0${idx}</span><div class="mission-symbol">${icon(m.icon,48)}</div><span class="card-status">${saved[m.id]?icon('check',13)+' Completed':'+'+' 100 XP'}</span><div class="preview-bubble">${esc(m.preview)}</div></div><div class="card-content"><span class="category">${m.category}</span><h3>${m.title}</h3><p>${m.desc}</p><div class="card-bottom"><span>${icon('clock',14)} ${m.time}</span><button data-start="${m.id}" aria-label="${saved[m.id]?'Replay':'Start'} ${m.title}">${saved[m.id]?'Replay mission':'Start mission'} ${icon('arrow',17)}</button></div></div></article>`;}
function startMission(id){active=missions.find(m=>m.id===id);if(!active)return;view='missions';round=0;selected=null;answers=[];sessionResult=null;render();focusMain();}
function choose(i){if(selected!==null)return;const options=round===0?active.options:active.next;if(!options[i])return;selected=i;answers[round]=options[i];renderMission();const feedback=$('#feedback');feedback.focus({preventScroll:true});feedback.scrollIntoView({behavior:'smooth',block:'nearest'});say('Choice selected. Read the explanation, then continue.');}
function advance(){if(selected===null)return;if(round===0){round=1;selected=null;renderMission();focusMain();}else{const score=answers.reduce((n,a)=>n+a.points,0);sessionResult=score;saved[active.id]={score:Math.max(saved[active.id]?.score||0,score)};persist();renderMission();focusMain();}}
function renderMission(){const m=active;if(sessionResult!==null){const next=missions.find(x=>!saved[x.id]&&x.id!==m.id);shell(`<section class="results"><span class="result-emblem">${icon('shield',56)}</span><div class="eyebrow">MISSION COMPLETE · CASE 0${missions.indexOf(m)+1}</div><h1>One mission.<br><span>A stronger instinct.</span></h1><p class="result-lesson">${m.takeaway}</p><div class="score-row"><div><strong>+${sessionResult}</strong><span>XP this attempt</span></div><div><strong>${saved[m.id].score}/100</strong><span>Your best score</span></div><div><strong>${done()}/6</strong><span>Missions explored</span></div></div><div class="review-list">${answers.map((a,i)=>`<div><span class="review-dot">${icon(a.points===50?'check':'info',19)}</span><div><small>DECISION ${i+1}</small><strong>${a.text}</strong><p>${a.feedback}</p></div></div>`).join('')}</div><p class="muted">XP reflects choices in this fictional mission, not a measure of your safety in real life. Your highest score is saved; replay to practice.</p><div class="result-actions">${next?`<button class="primary" data-start="${next.id}">Next mission ${icon('arrow')}</button>`:'<button class="primary" data-nav="progress">See your progress</button>'}<button class="secondary" data-start="${m.id}">Replay this mission</button><button class="text-button" data-nav="missions">Back to mission hub</button></div></section>`);return;}const opts=round===0?m.options:m.next;const picked=selected===null?null:opts[selected];shell(`<div class="mission-heading"><button class="text-button" data-nav="missions">← Mission hub</button><span>CASE 0${missions.indexOf(m)+1} / ${m.category}</span><span class="step-indicator"><i class="filled"></i><i class="${round===1?'filled':''}"></i> Decision ${round+1} of 2</span></div><section class="mission-intro"><div class="eyebrow">${m.skill.toUpperCase()}</div><h1>${m.title}</h1><p>${m.desc}</p></section><div class="investigation"><div><section class="scenario"><div class="scenario-top"><span class="sender-icon ${m.color}">${icon(m.icon,22)}</span><div><strong>${m.sender}</strong><span>FICTIONAL SCENARIO · NO REAL MESSAGES</span></div></div>${m.format==='voice'&&round===0?'<div class="waveform" aria-label="Illustrated voice message; transcript below">'+Array.from({length:42},(_,i)=>`<i style="height:${12+(i*17%37)}px"></i>`).join('')+'<span>TRANSCRIPT</span></div>':''}<blockquote>${esc(round===0?m.message:answers[0].branch)}</blockquote><p class="context">${round===0?m.context:'This is what happened after your first decision. Choose your next move.'}</p></section><section class="choices"><span class="eyebrow">YOUR MOVE</span><h2>${round===0?m.question:m.follow}</h2><div class="choice-list">${opts.map((o,i)=>`<button class="choice ${selected===i?'selected':''}" data-choice="${i}" ${selected!==null?'disabled':''}><span class="choice-letter">${String.fromCharCode(65+i)}</span><span>${esc(o.text)}</span><span class="choice-arrow">${selected===i?icon('check',18):icon('arrow',18)}</span></button>`).join('')}</div>${picked?`<div class="feedback ${picked.points===50?'positive':'reflect'}" id="feedback" tabindex="-1"><strong>${icon(picked.points===50?'check':'info',19)} ${picked.points===50?'A thoughtful move.':'A moment to rethink.'}</strong><p>${picked.feedback}</p><button class="primary" id="advance">${round===0?'See what happens next':'Finish mission'} ${icon('arrow',18)}</button></div>`:'<p class="choice-note">There’s no timer. Explore the clues and take your time.</p>'}</section></div><aside class="clue-panel"><div class="clue-title">${icon('eye',23)}<h2>Look a little closer</h2></div><p>Good decisions begin with good questions. Open a clue before you choose.</p>${m.clues.map(([title,body],i)=>`<details><summary><span>0${i+1}</span>${title}<b>+</b></summary><p>${body}</p></details>`).join('')}<div class="pause-card"><span>✦</span><strong>You can always pause.</strong><p>If a real interaction makes you uncomfortable, step away and speak with a trusted adult.</p><button class="text-button" data-help>Find support ${icon('arrow',15)}</button></div></aside></div>`);}
function renderGuide(){const rules=[['01','Pause','Pressure is a reason to slow down. You do not owe an immediate reply, a code, a photo, or your attention.','What is this message asking me to do?'],['02','Check','Find the original source. Verify an unexpected request using a contact method you already trust. Appearance, confidence, and familiar voices are not proof.','Can I verify this somewhere independent?'],['03','Protect','Share the least information needed. Keep login codes private. Consider what photos and small details reveal together.','Does this tool really need that information?'],['04','Connect','Keep real-world support close. Respect consent, avoid spreading harmful media, and ask a trusted adult when something worries you.','Who can help me think this through?']];shell(`<section class="page-intro"><span class="eyebrow">YOUR POCKET PLAYBOOK</span><h1>Four habits.<br><span>A smarter next move.</span></h1><p>You don’t need to spot every fake. You need a way to check.</p></section><div class="guide-grid">${rules.map(([n,t,b,q])=>`<article class="guide-card"><span class="guide-number">${n}</span><h2>${t}</h2><p>${b}</p><strong>${q}</strong></article>`).join('')}</div><section class="guide-bottom"><h2>A few things worth remembering</h2><ul><li>AI can be helpful and still make mistakes. Check important claims.</li><li>You cannot reliably identify every AI-generated image by how it looks.</li><li>A generated picture can cause real harm. Consent still matters.</li><li>A chatbot should not isolate you from people or pressure you into secrecy.</li><li>If you make a mistake online, you still deserve help. Talk to someone you trust.</li></ul><button class="primary" data-nav="missions">Put it into practice ${icon('arrow')}</button></section>`);}
function renderProgress(){shell(`<section class="page-intro"><span class="eyebrow">SMALL STEPS. STRONGER INSTINCTS.</span><h1>Your quest,<br><span>at your own pace.</span></h1><p>Replay any mission. Your best score stays with you in this browser.</p></section><div class="progress-totals"><div><strong>${done()}<small>/6</small></strong><span>Missions completed</span></div><div><strong>${total()}<small>/600</small></strong><span>Learning XP</span></div><div><strong>${done()===6?'Explorer':'Rookie'}</strong><span>Your journey so far</span></div></div><div class="skill-list">${missions.map(m=>`<article><span class="skill-icon ${m.color}">${icon(m.icon,23)}</span><div><h2>${m.skill}</h2><p>${m.title}</p></div><span class="skill-score">${saved[m.id]?`${saved[m.id].score}/100 XP`:'Not explored yet'}</span><button class="secondary" data-start="${m.id}">${saved[m.id]?'Replay':'Explore'}</button></article>`).join('')}</div><div class="progress-actions"><button class="primary" id="export">Download learning report ${icon('arrow',17)}</button><button class="text-button" id="reset">Reset progress</button></div><p class="muted">Your report includes mission results and learning points only — no name or personal data. XP is not a real-world safety assessment.</p>`);}
function exportReport(){const text=['REALITYQUEST — LEARNING REPORT','A practice record, not a safety assessment.',`${done()} of 6 missions completed · ${total()} / 600 XP`,'',...missions.flatMap(m=>[m.title,`Best result: ${saved[m.id]?saved[m.id].score+'/100 XP':'Not completed'}`,m.takeaway,'']),'All scenarios are fictional. Progress is saved only in this browser.'].join('\n');const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='RealityQuest-Learning-Report.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);say('Learning report downloaded.');}
$('#close-help').onclick=()=>$('#help').close();render();
